style.css:
@namespace url(http://www.w3.org/1999/xhtml);

/* Force dark blue background and light blue text on ALL elements */
* {
    background-color: rgba(0, 0, 139, 0.7) !important;
    color: #ADD8E6 !important;
    font-family: Arial, sans-serif !important;
    border-color: #87CEFA !important; /* Makes borders light blue */
}

/* Ensure the full page background is blue */
html, body {
    background-color: rgba(0, 0, 139, 0.9) !important; /* Stronger blue */
}

/* Force text readability */
h1, h2, h3, h4, h5, h6 {
    color: #B0E0E6 !important;
    text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.5) !important;
}

/* Links */
a {
    color: #87CEFA !important; /* Bright blue */
}
a:hover {
    color: #FFFFFF !important; /* White on hover */
}

/* Input fields */
input, textarea, select, button {
    background-color: rgba(0, 0, 139, 0.5) !important;
    color: #ADD8E6 !important;
    border: 1px solid #87CEFA !important;
}

/* Tables */
table, th, td {
    background-color: rgba(0, 0, 139, 0.8) !important;
    border: 1px solid #ADD8E6 !important;
}
